  booking?: Prisma.BookingOmit
  bookingHistory?: Prisma.BookingHistoryOmit
  eventAssignment?: Prisma.EventAssignmentOmit
  checkIn?: Prisma.CheckInOmit
  announcement?: Prisma.AnnouncementOmit
